-card label{gap:8px;font-size:13px;font-weight:550}.settings-card label>.help{font-weight:400;font-size:12px}.settings-card input,.settings-card select{min-height:44px}.broker-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.broker-options button{padding:16px;justify-content:flex-start;text-align:left;gap:12px;font-weight:400}.broker-options button>span:not(.choice-dot){display:grid;gap:5px;flex:1}.broker-options b{font-size:14px}.broker-options small{color:var(--muted);font-size:12px}.choice-dot{height:16px;width:16px;border:1px solid var(--border);border-radius:50%;flex-shrink:0}.broker-options button[aria-checked=true]{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}.broker-options button[aria-checked=true] .choice-dot{border:5px solid var(--accent);background:var(--surface)}.settings-password{position:relative}.settings-password input{padding-right:46px}.settings-password button{position:absolute;right:6px;top:6px;width:32px;height:32px;min-height:32px;padding:5px}.settings-note{display:flex;align-items:center;gap:7px;margin-top:16px;font-size:12px}.settings-actions{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:18px 24px;background:var(--surface-muted)}.settings-actions>span{display:flex;align-items:center;gap:8px}.settings-actions button{flex-shrink:0}.settings-tip{display:flex;align-items:flex-start;gap:12px;padding:0 6px;color:var(--muted)}.settings-tip>svg{margin-top:3px}.settings-tip b{font-size:13px;color:var(--text)}.settings-tip p{font-size:13px;line-height:1.7;margin-top:4px}.settings-tip button{padding:8px 0;min-height:32px;font-size:12px;color:var(--accent)}.device-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:20px 24px}.device-toolbar>div{display:flex;gap:8px}.managed-device-list{padding:0 24px}.managed-device{display:flex;align-items:center;gap:14px;padding:18px 0;border-top:1px solid var(--border)}.device-model-icon{wid