@media(max-width:800px){.settings-heading{margin:20px 0}.settings-heading h1{font-size:23px}.settings-layout{grid-template-columns:minmax(0,1fr);gap:20px}.settings-sidebar{position:static}.settings-navigation{display:flex;border-bottom:1px solid var(--border);gap:4px}.settings-navigation button{padding:12px 10px;border-radius:var(--radius-s) var(--radius-s) 0 0;justify-content:center;gap:7px}.settings-navigation button>span{flex:none}.settings-navigation small,.settings-navigation .nav-arrow,.settings-context{display:none}.settings-navigation button>svg{width:17px}.settings-card-heading,.settings-block,.account-summary{padding:20px}.device-toolbar{padding:16px 20px}.managed-device-list{padding:0 20px}.settings-actions,.settings-footnote{padding:16px 20px}.settings-heading>.btn{font-size:12px;padding:8px 12px;white-space:nowrap}.settings-heading>.btn svg{display:none}.settings-heading .help{max-width:240px}.settings-card-heading .settings-icon{width:38px;height:38px}.settings-card-heading{gap:12px}.settings-card-heading h2{font-size:16px}}
